import { prisma } from '../db';

export async function getAuthorName(postId: string) {
  const post = await prisma.post.findUnique({
    where: { id: postId },
    include: { author: true, comments: true, tags: true },
  });
  return post?.author.name;
}

export async function placeOrder(orderData: OrderInput) {
  const order = await prisma.order.create({ data: orderData });
  await prisma.inventory.update({
    where: { id: orderData.inventoryId },
    data: { quantity: { decrement: 1 } },
  });
  return order;
}

export async function getOrderTotal(orderId: string) {
  const order = await prisma.order.findUnique({
    where: { id: orderId },
    select: { total: true },
  });
  return order?.total;
}
